async ({ workspace: { search, edit } }) => {
  const [t, w] = await Promise.all([
    search("scripts/audit-runtime.ts", { path: "test/process" }),
    search("run: npm audit --omit=dev", { path: ".github/workflows" }),
  ]);
  const edits = [t.matches[0]!, ...w.matches].map((m) =>
    edit(m.file, { revision: m.revision, changes: [{ kind: "replace", start: m.anchor, content: m.text.replace("scripts/audit-runtime.ts", "scripts/audit-runtime.js").replace("npm audit --omit=dev", "npm run audit:runtime") }] }));
  return (await Promise.all(edits)).map((e) => e.file);
}
